1	package water
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"testing"
9		"time"
10	)
11	
12	// 限值只能属于登记它的（采样点，项目）：两个字段各自相同才算同一组。
13	// 编号与项目名内部允许包含 U+0000，不能用单字符拼接键把不同组合撞成一组。
14	func TestLimitGroupOwnership(t *testing.T) {
15		s, _ := open(t)
16		zeroPoint := "P\x00A" // 〈零〉在编号中间
17		zeroItem := "A\x00B"  // 〈零〉在项目名中间
18		mustPoint(t, s, zeroPoint, "带零编号")
19		mustPoint(t, s, "P", "普通编号")
20	
21		eff := at(1, 0)
22		// 两组在同一时刻分别登记上限 10 和 5，互不报生效时间重复
23		mustLimit(t, s, zeroPoint, "B", 10, eff)
24		mustLimit(t, s, "P", zeroItem, 5, eff)
25	
26		sampled := at(2, 0)
27		mustSample(t, s, "SZ", zeroPoint, sampled, Measurement{Item: "B", Value: 7})
28		mustSample(t, s, "SN", "P", sampled, Measurement{Item: zeroItem, Value: 7})
29	
30		rz, err := s.Confirm("SZ")
31		if err != nil {
32			t.Fatalf("Confirm SZ: %v", err)
33		}
34		if rz.Exceeded || len(rz.Results) != 1 {
35			t.Fatalf("7 <= 10 应达标: %+v", rz)
36		}
37		if r := rz.Results[0]; r.Item != "B" || r.Value != 7 || r.Limit != 10 ||
38			!r.LimitEffective.Equal(eff) || r.Exceeded {
39			t.Fatalf("前者判定依据错误: %+v", r)
40		}
41	
42		rn, err := s.Confirm("SN")
43		if err != nil {
44			t.Fatalf("Confirm SN: %v", err)
45		}
46		if !rn.Exceeded || len(rn.Results) != 1 {
47			t.Fatalf("7 > 5 应超标: %+v", rn)
48		}
49		if r := rn.Results[0]; r.Item != zeroItem || r.Value != 7 || r.Limit != 5 ||
50			!r.LimitEffective.Equal(eff) || !r.Exceeded {
51			t.Fatalf("后者判定依据错误: %+v", r)
52		}
53	
54		// 按采样点查看：各自只看到本组样品与本组判定依据
55		for _, c := range []struct {
56			point string
57			id    string
58			lim   float64
59			item  string
60		}{
61			{zeroPoint, "SZ", 10, "B"},
62			{"P", "SN", 5, zeroItem},
63		} {
64			list, err := s.ListByPoint(c.point)
65			if err != nil || len(list) != 1 {
66				t.Fatalf("ListByPoint(%q): %+v err=%v", c.point, list, err)
67			}
68			got := list[0]
69			if got.ID != c.id || len(got.Results) != 1 {
70				t.Fatalf("按点查看串组: %+v", got)
71			}
72			if r := got.Results[0]; r.Item != c.item || r.Limit != c.lim ||
73				!r.LimitEffective.Equal(eff) {
74				t.Fatalf("按点查看的判定依据错误: %+v", r)
75			}
76		}
77	}
78	
79	// 只登记了一组限值时，另一组的样品必须因缺适用上限拒绝确认：
80	// 保持待判定、不留部分结果、不借用另一组的限值。
81	func TestLimitGroupMissingLimit(t *testing.T) {
82		s, _ := open(t)
83		zeroPoint := "P\x00A"
84		zeroItem := "A\x00B"
85		mustPoint(t, s, zeroPoint, "带零编号")
86		mustPoint(t, s, "P", "普通编号")
87		mustLimit(t, s, zeroPoint, "B", 10, at(1, 0))
88		// "P"/"A\x00B" 没有登记任何限值
89	
90		mustSample(t, s, "SN", "P", at(2, 0), Measurement{Item: zeroItem, Value: 7})
91		if _, err := s.Confirm("SN"); !errors.Is(err, ErrMissingLimit) {
92			t.Fatalf("另一组缺上限应拒绝，got %v", err)
93		}
94		list, err := s.ListByPoint("P")
95		if err != nil || len(list) != 1 {
96			t.Fatalf("list: %+v err=%v", list, err)
97		}
98		if got := list[0]; got.Status != StatusPending || got.Results != nil || got.Exceeded {
99			t.Fatalf("拒绝后必须保持待判定且无部分结果: %+v", got)
100		}
101		if _, ok, err := s.LatestResult("P"); err != nil || ok {
102			t.Fatalf("另一组不应出现已确认结果 ok=%v err=%v", ok, err)
103		}
104	
105		// 被拒绝的确认不影响已有组的判定
106		mustSample(t, s, "SZ", zeroPoint, at(2, 0), Measurement{Item: "B", Value: 7})
107		rz, err := s.Confirm("SZ")
108		if err != nil || rz.Exceeded || rz.Results[0].Limit != 10 {
109			t.Fatalf("已有组判定受影响: %+v err=%v", rz, err)
110		}
111	}
112	
113	// 两组各有多版限值时，独立选择采样当时已生效的最近一版；
114	// 另一组更晚生效的版本不影响本组；边界时刻与等于上限的规则保持不变。
115	func TestLimitGroupVersionsIndependent(t *testing.T) {
116		s, _ := open(t)
117		zeroPoint := "P\x00A"
118		zeroItem := "A\x00B"
119		mustPoint(t, s, zeroPoint, "带零编号")
120		mustPoint(t, s, "P", "普通编号")
121	
122		// zeroPoint/B：10@9/1、20@9/10
123		mustLimit(t, s, zeroPoint, "B", 10, at(1, 0))
124		mustLimit(t, s, zeroPoint, "B", 20, at(10, 0))
125		// P/zeroItem：5@9/1、50@9/20（另一组更晚的 20@9/10 与本组互不干涉）
126		mustLimit(t, s, "P", zeroItem, 5, at(1, 0))
127		mustLimit(t, s, "P", zeroItem, 50, at(20, 0))
128	
129		// 9/10 采样：zeroPoint 组恰好生效 20（边界用新版，等于上限达标）
130		mustSample(t, s, "SZ", zeroPoint, at(10, 0), Measurement{Item: "B", Value: 20})
131		rz, err := s.Confirm("SZ")
132		if err != nil {
133			t.Fatalf("Confirm SZ: %v", err)
134		}
135		if rz.Exceeded || rz.Results[0].Limit != 20 ||
136			!rz.Results[0].LimitEffective.Equal(at(10, 0)) {
137			t.Fatalf("边界时刻应用该版且等于上限达标: %+v", rz.Results[0])
138		}
139	
140		// 9/15 采样：P 组只能用 5（本组的 50 尚未生效，另一组的 20 不能借用）
141		mustSample(t, s, "SN", "P", at(15, 0), Measurement{Item: zeroItem, Value: 7})
142		rn, err := s.Confirm("SN")
143		if err != nil {
144			t.Fatalf("Confirm SN: %v", err)
145		}
146		if !rn.Exceeded || rn.Results[0].Limit != 5 ||
147			!rn.Results[0].LimitEffective.Equal(at(1, 0)) {
148			t.Fatalf("本组不能受另一组版本影响: %+v", rn.Results[0])
149		}
150	
151		// 同组同一时刻（不同时区表示）仍报重复，且不覆盖原值
152		cst5 := time.Date(2026, 9, 10, 8, 0, 0, 0, time.FixedZone("CST", 8*3600))
153		if _, err := s.SetLimit(zeroPoint, "B", 99, cst5); !errors.Is(err, ErrDuplicateLimitTime) {
154			t.Fatalf("同组同一时刻换时区表示应报重复, got %v", err)
155		}
156		mustSample(t, s, "SZ2", zeroPoint, at(11, 0), Measurement{Item: "B", Value: 25})
157		rz2, err := s.Confirm("SZ2")
158		if err != nil || rz2.Results[0].Limit != 20 || !rz2.Exceeded {
159			t.Fatalf("被拒绝的登记不得覆盖原值: %+v err=%v", rz2.Results[0], err)
160		}
161		// 另一组记录也不受这次拒绝影响
162		if got := s.limits[limitGroup{pointID: "P", item: zeroItem}]; len(got) != 2 {
163			t.Fatalf("拒绝操作改动了另一组记录: %+v", got)
164		}
165	}
166	
167	// 旧版本曾把限值按 "pointID + U+0000 + item" 单键落盘，
168	// 包含 U+0000 的不同组合会共用同一个键。重新打开旧文件时必须按每条
169	// 限值自身的采样点与项目重新分组，已确认样品的原结论与所用限值保持不变。
170	func TestLimitGroupReloadOldCollidedFile(t *testing.T) {
171		dir := t.TempDir()
172		zeroPoint := "P\x00A"
173		zeroItem := "A\x00B"
174		eff := at(1, 0)
175	
176		// 手工构造旧格式文件：两组限值落在同一个碰撞键下，
177		// 但每条记录各自带着正确的 pointId/item。
178		oldKey := zeroPoint + "\x00" + "B" // 旧算法的键，与 "P" + "\x00" + zeroItem 相同
179		if oldKey != "P"+"\x00"+zeroItem {
180			t.Fatal("test setup: 两个组合应拼出同一个旧键")
181		}
182		old := diskState{
183			Points: map[string]SamplingPoint{
184				zeroPoint: {ID: zeroPoint, Name: "带零编号"},
185				"P":       {ID: "P", Name: "普通编号"},
186			},
187			Limits: map[string][]Limit{
188				oldKey: {
189					{PointID: zeroPoint, Item: "B", Value: 10, Effective: eff},
190					{PointID: "P", Item: zeroItem, Value: 5, Effective: eff},
191				},
192			},
193			Samples: map[string]*Sample{
194				"SN": {
195					ID: "SN", PointID: "P", SampledAt: at(2, 0),
196					Measurements: []Measurement{{Item: zeroItem, Value: 7}},
197					Status:       StatusConfirmed, Exceeded: true,
198					Results: []ItemResult{{
199						Item: zeroItem, Value: 7, Limit: 5,
200						LimitEffective: eff, Exceeded: true,
201					}},
202				},
203			},
204		}
205		data, err := json.MarshalIndent(old, "", "  ")
206		if err != nil {
207			t.Fatalf("marshal old file: %v", err)
208		}
209		if err := os.WriteFile(filepath.Join(dir, "water-data.json"), data, 0o644); err != nil {
210			t.Fatalf("write old file: %v", err)
211		}
212	
213		s, err := Open(dir)
214		if err != nil {
215			t.Fatalf("Open old file: %v", err)
216		}
217		defer s.Close()
218	
219		if got := s.limits[limitGroup{pointID: zeroPoint, item: "B"}]; len(got) != 1 || got[0].Value != 10 {
220			t.Fatalf("旧文件重新分组失败（zeroPoint 组）: %+v", got)
221		}
222		if got := s.limits[limitGroup{pointID: "P", item: zeroItem}]; len(got) != 1 || got[0].Value != 5 {
223			t.Fatalf("旧文件重新分组失败（P 组）: %+v", got)
224		}
225	
226		// 已确认样品保留原结论与所用限值，不自动重新判定
227		kept, err := s.Confirm("SN")
228		if err != nil {
229			t.Fatalf("Confirm kept sample: %v", err)
230		}
231		if r := kept.Results[0]; !kept.Exceeded || r.Item != zeroItem ||
232			r.Value != 7 || r.Limit != 5 || !r.LimitEffective.Equal(eff) {
233			t.Fatalf("已确认样品结论被改动: %+v", kept)
234		}
235	
236		// 同一时刻两组各自再登记仍互不冲突；同组重复仍拒绝
237		if _, err := s.SetLimit(zeroPoint, "B", 11, at(5, 0)); err != nil {
238			t.Fatalf("两组独立补录应成功: %v", err)
239		}
240		if _, err := s.SetLimit("P", zeroItem, 6, at(5, 0)); err != nil {
241			t.Fatalf("两组独立补录应成功: %v", err)
242		}
243		if _, err := s.SetLimit(zeroPoint, "B", 12, eff); !errors.Is(err, ErrDuplicateLimitTime) {
244			t.Fatalf("同组同一时刻仍应报重复, got %v", err)
245		}
246	
247		// 再次落盘并重新打开，归属仍然正确
248		if err := s.Close(); err != nil {
249			t.Fatalf("Close: %v", err)
250		}
251		s2, err := Open(dir)
252		if err != nil {
253			t.Fatalf("reopen: %v", err)
254		}
255		defer s2.Close()
256		if got := s2.limits[limitGroup{pointID: zeroPoint, item: "B"}]; len(got) != 2 {
257			t.Fatalf("重开后版本丢失或串组: %+v", got)
258		}
259		if got := s2.limits[limitGroup{pointID: "P", item: zeroItem}]; len(got) != 2 {
260			t.Fatalf("重开后版本丢失或串组: %+v", got)
261		}
262	}
